#include <bits/stdc++.h>
using namespace std;

class ATM { long long cnt[5]={}; int v[5]={20,50,100,200,500}; public: ATM() {} void deposit(vector<int> banknotesCount) { for(int i=0;i<5;++i) cnt[i]+=banknotesCount[i]; } vector<int> withdraw(int amount) { vector<int> take(5); for(int i=4;i>=0;--i){ take[i]=min(cnt[i],(long long)amount/v[i]); amount-=take[i]*v[i]; } if(amount) return {-1}; for(int i=0;i<5;++i)cnt[i]-=take[i]; return take; } };
